import{_ as t,o as i,c as a,ag as r}from"./chunks/framework.BpFM782D.js";const p=JSON.parse('{"title":"article-writing","description":"","frontmatter":{},"headers":[],"relativePath":"en/skills/article-writing.md","filePath":"en/skills/article-writing.md"}'),l={name:"en/skills/article-writing.md"};function o(n,e,s,c,d,h){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="article-writing" tabindex="-1">article-writing <a class="header-anchor" href="#article-writing" aria-label="Permalink to &quot;article-writing&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Name</td><td>article-writing</td></tr><tr><td>Description</td><td>Write articles, guides, blog posts, tutorials, newsletter issues, and other long-form content in a distinctive voice derived from supplied examples or brand guidance. Use when the user wants polished written content longer than a paragraph, especially when voice consistency, structure, and credibility matter.</td></tr><tr><td>Origin</td><td>ECC</td></tr><tr><td>Source Directory</td><td><code>skills/article-writing/</code></td></tr></tbody></table><hr><h1 id="article-writing-1" tabindex="-1">Article Writing <a class="header-anchor" href="#article-writing-1" aria-label="Permalink to &quot;Article Writing&quot;">​</a></h1><p>Write long-form content that sounds like a real person or brand, not generic AI output.</p><h2 id="when-to-activate" tabindex="-1">When to Activate <a class="header-anchor" href="#when-to-activate" aria-label="Permalink to &quot;When to Activate&quot;">​</a></h2><ul><li>drafting blog posts, essays, launch posts, guides, tutorials, or newsletter issues</li><li>turning notes, transcripts, or research into polished articles</li><li>matching an existing founder, operator, or brand voice from examples</li><li>tightening structure, pacing, and evidence in already-written long-form copy</li></ul><h2 id="core-rules" tabindex="-1">Core Rules <a class="header-anchor" href="#core-rules" aria-label="Permalink to &quot;Core Rules&quot;">​</a></h2><ol><li>Lead with the concrete thing: example, output, anecdote, number, screenshot description, or code block.</li><li>Explain after the example, not before.</li><li>Prefer short, direct sentences over padded ones.</li><li>Use specific numbers when available and sourced.</li><li>Never invent biographical facts, company metrics, or customer evidence.</li></ol><h2 id="voice-capture-workflow" tabindex="-1">Voice Capture Workflow <a class="header-anchor" href="#voice-capture-workflow" aria-label="Permalink to &quot;Voice Capture Workflow&quot;">​</a></h2><p>If the user wants a specific voice, collect one or more of:</p><ul><li>published articles</li><li>newsletters</li><li>X / LinkedIn posts</li><li>docs or memos</li><li>a short style guide</li></ul><p>Then extract:</p><ul><li>sentence length and rhythm</li><li>whether the voice is formal, conversational, or sharp</li><li>favored rhetorical devices such as parentheses, lists, fragments, or questions</li><li>tolerance for humor, opinion, and contrarian framing</li><li>formatting habits such as headers, bullets, code blocks, and pull quotes</li></ul><p>If no voice references are given, default to a direct, operator-style voice: concrete, practical, and low on hype.</p><h2 id="banned-patterns" tabindex="-1">Banned Patterns <a class="header-anchor" href="#banned-patterns" aria-label="Permalink to &quot;Banned Patterns&quot;">​</a></h2><p>Delete and rewrite any of these:</p><ul><li>generic openings like &quot;In today&#39;s rapidly evolving landscape&quot;</li><li>filler transitions such as &quot;Moreover&quot; and &quot;Furthermore&quot;</li><li>hype phrases like &quot;game-changer&quot;, &quot;cutting-edge&quot;, or &quot;revolutionary&quot;</li><li>vague claims without evidence</li><li>biography or credibility claims not backed by provided context</li></ul><h2 id="writing-process" tabindex="-1">Writing Process <a class="header-anchor" href="#writing-process" aria-label="Permalink to &quot;Writing Process&quot;">​</a></h2><ol><li>Clarify the audience and purpose.</li><li>Build a skeletal outline with one purpose per section.</li><li>Start each section with evidence, example, or scene.</li><li>Expand only where the next sentence earns its place.</li><li>Remove anything that sounds templated or self-congratulatory.</li></ol><h2 id="structure-guidance" tabindex="-1">Structure Guidance <a class="header-anchor" href="#structure-guidance" aria-label="Permalink to &quot;Structure Guidance&quot;">​</a></h2><h3 id="technical-guides" tabindex="-1">Technical Guides <a class="header-anchor" href="#technical-guides" aria-label="Permalink to &quot;Technical Guides&quot;">​</a></h3><ul><li>open with what the reader gets</li><li>use code or terminal examples in every major section</li><li>end with concrete takeaways, not a soft summary</li></ul><h3 id="essays-opinion-pieces" tabindex="-1">Essays / Opinion Pieces <a class="header-anchor" href="#essays-opinion-pieces" aria-label="Permalink to &quot;Essays / Opinion Pieces&quot;">​</a></h3><ul><li>start with tension, contradiction, or a sharp observation</li><li>keep one argument thread per section</li><li>use examples that earn the opinion</li></ul><h3 id="newsletters" tabindex="-1">Newsletters <a class="header-anchor" href="#newsletters" aria-label="Permalink to &quot;Newsletters&quot;">​</a></h3><ul><li>keep the first screen strong</li><li>mix insight with updates, not diary filler</li><li>use clear section labels and easy skim structure</li></ul><h2 id="quality-gate" tabindex="-1">Quality Gate <a class="header-anchor" href="#quality-gate" aria-label="Permalink to &quot;Quality Gate&quot;">​</a></h2><p>Before delivering:</p><ul><li>verify factual claims against provided sources</li><li>remove filler and corporate language</li><li>confirm the voice matches the supplied examples</li><li>ensure every section adds new information</li><li>check formatting for the intended platform</li></ul>',30)])])}const g=t(l,[["render",o]]);export{p as __pageData,g as default};
